B.bUZ=new A.bw(6,"\u0644\u0650\u062a\u064f\u0646\u0630\u0650\u0631\u064e \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0645\u0651\u064e\u0627\u0653 \u0623\u064f\u0646\u0630\u0650\u0631\u064e \u0621\u064e\u0627\u0628\u064e\u0627\u0653\u0624\u064f\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u063a\u064e\u0670\u0641\u0650\u0644\u064f\u0648\u0646\u064e","Litundzira qaumam maa undzira aabaaa-uhum fahum ghaafiluun.","agar engkau memberi peringatan kepada suatu kaum yang nenek moyangnya belum pernah diberi peringatan, karena itu mereka lalai.")
B.bV_=new A.bw(7,"\u0644\u064e\u0642\u064e\u062f\u0652 \u062d\u064e\u0642\u0651\u064e \u0671\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0639\u064e\u0644\u064e\u0649\u0670\u0653 \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u0650\u0647\u0650\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e","Laqad haqqal-qaulu 'alaaa aktsarihim fahum laa yu'minuun.","Sungguh, pasti berlaku perkataan (hukuman) terhadap kebanyakan mereka, karena mereka tidak beriman.")
B.bUt=new A.bw(8,"\u0625\u0650\u0646\u0651\u064e\u0627 \u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0641\u0650\u0649\u0653 \u0623\u064e\u0639\u0652\u0646\u064e\u0670\u0642\u0650\u0647\u0650\u0645\u0652 \u0623\u064e\u063a\u0652\u0644\u064e\u0670\u0644\u064b\u0627 \u0641\u064e\u0647\u0650\u0649\u064e \u0625\u0650\u0644\u064e\u0649 \u0671\u0644\u0652\u0623\u064e\u0630\u0652\u0642\u064e\u0627\u0646\u0650 \u0641\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0642\u0652\u0645\u064e\u062d\u064f\u0648\u0646\u064e","Innaa ja'alnaa fiii a'naaqihim aghlaalan fahiya ilal-adzqaani fahum muqmahuun.","Sungguh, Kami telah memasang belenggu di leher mereka, lalu tangan mereka (diangkat) ke dagu, karena itu mereka tertengadah.")
B.bV7=new A.bw(9,"\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627 \u0645\u0650\u0646\u06e2 \u0628\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0633\u064e\u062f\u0651\u064b\u0627 \u0648\u064e\u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0641\u0650\u0647\u0650\u0645\u0652 \u0633\u064e\u062f\u0651\u064b\u0627 \u0641\u064e\u0623\u064e\u063a\u0652\u0634\u064e\u064a\u0652\u0646\u064e\u0670\u0647\u064f\u0645\u0652 \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e","Wa ja'alnaa mim baini aidiihim saddaw wa min khalfihim saddan fa-aghsyainaahum fahum laa yubshiruun.","Dan Kami jadikan di hadapan mereka sekat (dinding) dan di belakang mereka sekat, dan Kami tutup (mata) mereka sehingga mereka tidak dapat melihat.")
B.bV8=new A.bw(10,"\u0648\u064e\u0633\u064e\u0648\u064e\u0627\u0653\u0621\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0621\u064e\u0623\u064e\u0646\u0630\u064e\u0631\u0652\u062a\u064e\u0647\u064f\u0645\u0652 \u0623\u064e\u0645\u0652 \u0644\u064e\u0645\u0652 \u062a\u064f\u0646\u0630\u0650\u0631\u0652\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e","Wa sawaaa-un 'alaihim a-andzartahum am lam tundzirhum laa yu'minuun.","Dan sama saja bagi mereka, apakah engkau memberi peringatan kepada mereka atau engkau tidak memberi peringatan kepada mereka, mereka tidak akan beriman juga.")
B.bUN=new A.bw(11,"\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u062a\u064f\u0646\u0630\u0650\u0631\u064f \u0645\u064e\u0646\u0650 \u0671\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0671\u0644\u0630\u0651\u0650\u0643\u0652\u0631\u064e \u0648\u064e\u062e\u064e\u0634\u0650\u0649\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0670\u0646\u064e \u0628\u0650\u0671\u0644\u0652\u063a\u064e\u064a\u0652\u0628\u0650 \u06d6 \u0641\u064e\u0628\u064e\u0634\u0651\u0650\u0631\u0652\u0647\u064f \u0628\u0650\u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064d \u0648\u064e\u0623\u064e\u062c\u0652\u0631\u064d \u0643\u064e\u0631\u0650\u064a\u0645\u064d","Innamaa tundziru manittaba'adz-dzikra wa khasyiyar-rahmaana bil-ghaib, fabasysyirhu bimaghfiratiw wa ajrin kariim.","Sesungguhnya engkau hanya memberi peringatan kepada orang-orang yang mau mengikuti peringatan dan yang takut kepada Tuhan Yang Maha Pengasih walaupun mereka tidak melihat-Nya. Maka berilah mereka kabar gembira dengan ampunan dan pahala yang mulia.")
B.bV1=new A.bw(12,"\u0625\u0650\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0646\u064f\u062d\u0652\u0649\u0650 \u0671\u0644\u0652\u0645\u064e\u0648\u0652\u062a\u064e\u0649\u0670 \u0648\u064e\u0646\u064e\u0643\u0652\u062a\u064f\u0628\u064f \u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064f\u0648\u0627\u06df \u0648\u064e\u0621\u064e\u0627\u062b\u064e\u0670\u0631\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0643\u064f\u0644\u0651\u064e \u0634\u064e\u0649\u0652\u0621\u064d \u0623\u064e\u062d\u0652\u0635\u064e\u064a\u0652\u0646\u064e\u0670\u0647\u064f \u0641\u0650\u0649\u0653 \u0625\u0650\u0645\u064e\u0627\u0645\u064d \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d","Innaa nahnu nuhyil-mautaa wa naktubu maa qaddamuu wa aatsaarahum, wa kulla syai-in ahshainaahu fiii imaamim mubiin.","Sungguh, Kamilah yang menghidupkan orang-orang yang mati, dan Kamilah yang mencatat apa yang telah mereka kerjakan dan bekas-bekas yang mereka tinggalkan. Dan segala sesuatu Kami kumpulkan dalam Kitab yang jelas (Lauh Mahfuzh).")
B.bV9=new A.bw(13,"\u0648\u064e\u0671\u0636\u0652\u0631\u0650\u0628\u0652 \u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u062b\u064e\u0644\u064b\u0627 \u0623\u064e\u0635\u0652\u062d\u064e\u0670\u0628\u064e \u0671\u0644\u0652\u0642\u064e\u0631\u0652\u064a\u064e\u0629\u0650 \u0625\u0650\u0630\u0652 \u062c\u064e\u0627\u0653\u0621\u064e\u0647\u064e\u0627 \u0671\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u064f\u0648\u0646\u064e","Wadhrib lahum matsalan ash-haabal-qaryati idz jaaa-ahal-mursaluun.","Dan buatlah suatu perumpamaan bagi mereka, yaitu penduduk suatu negeri, ketika utusan-utusan datang kepada mereka;")
B.bV2=new A.bw(14,"\u0625\u0650\u0630\u0652 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0671\u062b\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u0641\u064e\u0643\u064e\u0630\u0651\u064e\u0628\u064f\u0648\u0647\u064f\u0645\u064e\u0627 \u0641\u064e\u0639\u064e\u0632\u0651\u064e\u0632\u0652\u0646\u064e\u0627 \u0628\u0650\u062b\u064e\u0627\u0644\u0650\u062b\u064d \u0641\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0653\u0627\u06df \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645 \u0645\u0651\u064f\u0631\u0652\u0633\u064e\u0644\u064f\u0648\u0646\u064e","Idz arsalnaaa ilaihimutsnaini fakadz-dzabuuhumaa fa'azzaznaa bitaalitsin faqaaluuu innaaa ilaikum mursaluun.",'(yaitu) ketika Kami mengutus kepada mereka dua orang utusan, lalu mereka mendustakan keduanya; kemudian Kami kuatkan dengan (utusan) yang ketiga, maka ketiga (utusan itu) berkata, "Sungguh, kami adalah orang-orang yang diutus kepadamu."')
B.bUS=new A.bw(15,"\u0642\u064e\u0627\u0644\u064f\u0648\u0627\u06df \u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0628\u064e\u0634\u064e\u0631\u064c \u0645\u0651\u0650\u062b\u0652\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0645\u064e\u0627\u0653 \u0623\u064e\u0646\u0632\u064e\u0644\u064e \u0671\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0670\u0646\u064f \u0645\u0650\u0646 \u0634\u064e\u0649\u0652\u0621\u064d \u0625\u0650\u0646\u0652 \u0623\u064e\u0646\u062a\u064f\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u062a\u064e\u0643\u0652\u0630\u0650\u0628\u064f\u0648\u0646\u064e","Qaaluu maaa antum illaa basyarum mitslunaa wa maaa anzalar-rahmaanu min syai-in in antum illaa takdzibuun.",'Mereka (penduduk negeri) menjawab, "Kamu ini hanyalah manusia seperti kami, dan (Allah) Yang Maha Pengasih tidak menurunkan sesuatu apa pun; kamu hanyalah berdusta belaka."')
